'use strict';
const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={provider:window.PulseExperience.context.provider,scenario:window.PulseExperience.context.sample,view:window.PulseExperience.audience==='business'?'nis2':'overview',query:'',severity:'all'};
const severityOrder={critical:0,high:1,medium:2,low:3,info:4};
const business=()=>window.PulseExperience.audience==='business';
const report=()=>window.PULSE_REPORTS[state.provider][state.scenario];
const sorted=()=>[...report().findings].sort((a,b)=>(severityOrder[a.severity]??5)-(severityOrder[b.severity]??5));
const severityPill=s=>`<span class="pill ${['critical','high'].includes(s)?'red':s==='medium'?'amber':'blue'}">${esc(s)}</span>`;
const row=f=>`<button type="button" class="finding-row" data-finding="${esc(f.id)}"><span><strong>${esc(business()?window.PulseBusiness.title(f):f.title)}</strong><small>${business()?esc(window.PulseBusiness.impact(f)):esc(f.id)+' · '+esc(f.classification.replaceAll('-',' '))}</small></span><span class="finding-meta">${business()?`<span class="pill ${f.classification==='confirmed-risk'?'red':'amber'}">${esc(window.PulseBusiness.status(f))}</span>`:''}${severityPill(f.severity)}<span class="arrow" aria-hidden="true">↗</span></span></button>`;
function render(){const summary=$('business-summary');if(summary.parentElement!==$('main'))$('assessment-view').before(summary);renderTabs();const r=report(),fs=r.findings,critical=fs.filter(f=>f.severity==='critical').length,high=fs.filter(f=>f.severity==='high').length,validation=fs.filter(f=>f.classification==='requires-validation').length;const success=r.coverage.collectors.filter(c=>c.status==='success').length,total=r.coverage.collectors.length;$('score').textContent=r.score.overall;$('score-ring').style.setProperty('--score',r.score.overall);$('score-title').textContent=r.coverage.partial?'A score with blind spots':critical+high?'Review priority risks':'A stronger starting point';$('score-description').textContent=r.coverage.partial?'Interpret this score alongside uncollected evidence.':critical+high?'Prioritize the findings and validate their context.':'Review remaining signals and assessment boundaries.';$('grade').textContent=`Engine grade ${r.score.grade} · ${state.provider==='auth0'?'Auth0 CIAM':'Okta Workforce'}`;$('finding-total').textContent=`${fs.length} findings`;$('stats').innerHTML=`<div class="stat"><span class="stat-label">Critical</span><strong>${critical}</strong><small>Highest severity</small></div><div class="stat"><span class="stat-label">High</span><strong>${high}</strong><small>Priority review</small></div><div class="stat"><span class="stat-label">To validate</span><strong>${validation}</strong><small>Requires context</small></div>`;$('coverage-summary').textContent=`${success} / ${total} collectors successful`;$('coverage-notice').innerHTML=r.coverage.partial?'<div class="notice"><strong>Partial coverage.</strong> Some evidence could not be collected. Missing evidence is not proof that a control is safe.</div>':'';document.querySelectorAll('[role=tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.view===state.view)));$('assessment-view').setAttribute('aria-labelledby','tab-'+state.view);if(business()){$('business-summary').innerHTML=window.PulseBusiness.metrics(r);$('sample-context').innerHTML=`Production · synthetic sample<br> Evidence collected ${esc(new Date(r.provider.collectedAt).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}))}`;}renderView();if(business()&&state.view==='nis2')$('assessment-view').querySelector('.nis2-focus').after(summary);}
function renderView(){if(state.view==='nis2'){renderMaterial();return;}const r=report(),view=$('assessment-view');if(state.view==='overview'){view.innerHTML=`<div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>Start with these findings</h2><p>Highest severity first · evidence behind every result</p></div><button class="textlink" data-view="findings">View all ↗</button></div>${sorted().slice(0,4).map(row).join('')||'<p class="empty">No findings in this sample. Review positive signals and collection boundaries before drawing conclusions.</p>'}</section><section class="panel"><div class="panel-head"><div><h2>Where the score comes from</h2><p>Weighted category points, as reported by the engine</p></div></div>${r.categories.map(c=>`<div class="bar-row"><div class="bar-label"><span>${esc(c.name)}</span><b>${c.assessed?`${c.score??0} / ${c.weight}`:'Not assessed'}</b></div><div class="bar-track"><span style="width:${c.assessed?Math.max(0,Math.min(100,(c.score||0)/c.weight*100)):0}%"></span></div></div>`).join('')}<p class="section-note">Provider scoring models differ. Scores are posture indicators, not a certification or a direct provider ranking.</p></section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Positive signals</h2><span class="pill green">Keep what is working</span></div>${r.positiveSignals.length?r.positiveSignals.slice(0,3).map(s=>`<p style="font-size:14px;margin-top:10px"><strong>${esc(s.title)}</strong> <span class="muted">${esc(s.detail)}</span></p>`).join(''):'<p class="empty">No positive signals are supplied for this sample.</p>'}</section>`;}
else if(state.view==='findings'){view.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>${business()?'Findings':'Findings & evidence'}</h2><p>${business()?'Review business impact, then open a finding for the next action.':'Inspect classification, evidence and validation needs.'}</p></div><span class="pill">${r.findings.length} total</span></div><div class="filters"><input id="finding-search" type="search" aria-label="Search findings" placeholder="Search finding or rule ID" value="${esc(state.query)}"><select id="severity-filter" aria-label="Filter by severity"><option value="all">All severities</option>${Object.keys(severityOrder).map(s=>`<option value="${s}" ${state.severity===s?'selected':''}>${s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select></div><div id="finding-results"></div></section>`;renderResults();$('finding-search').addEventListener('input',e=>{state.query=e.target.value;renderResults();});$('severity-filter').addEventListener('change',e=>{state.severity=e.target.value;renderResults();});}
else if(state.view==='coverage'){view.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>What was actually collected</h2><p>Collector success does not guarantee exhaustive resource coverage.</p></div><span class="pill ${r.coverage.partial?'amber':'green'}">${r.coverage.partial?'Partial coverage':'No reported collector gaps'}</span></div><div class="table-wrap"><table><thead><tr><th>Collector</th><th>Reported state</th><th>Required scopes</th><th>Count</th></tr></thead><tbody>${r.coverage.collectors.map(c=>`<tr><td>${esc(c.collector)}</td><td><span class="pill ${c.status==='success'?'green':'amber'}">${esc(c.status)}</span></td><td><code>${esc((c.requiredScopes||[]).join(', ')||'Not specified')}</code></td><td>${c.count??'—'}</td></tr>`).join('')}</tbody></table></div>${r.coverage.missingScopes.length?`<p class="section-note"><strong>Missing scopes:</strong> ${esc(r.coverage.missingScopes.join(', '))}</p>`:''}<h3 style="margin-top:24px">What this assessment does not establish</h3><ul class="section-note">${r.limitations.map(l=>`<li>${esc(l)}</li>`).join('')}</ul></section>`;}
else if(state.view==='plan'&&business()){view.innerHTML=window.PulseBusiness.plan(r);}
else{view.innerHTML=`<div class="notice neutral"><strong>Action Plans · recommended next steps.</strong> Assign an owner, implement the change and collect validation evidence outside this demo. No completion or ownership is recorded in these samples.</div><div class="plan-grid">${r.remediationPlan.buckets.map(b=>`<section class="panel"><div class="panel-head"><div><h2>${esc(b.name)}</h2><p>${esc(b.window)}</p></div></div>${b.items.map(i=>`<div class="plan-item">${i.severity?severityPill(i.severity):''}<p style="margin-top:9px">${esc(i.action)}</p><small>Expected outcome: ${esc(i.expectedOutcome)}</small><dl class="action-status"><div><dt>Owner</dt><dd>Unassigned</dd></div><div><dt>Status</dt><dd>Recommended</dd></div><div><dt>Validation</dt><dd>Not verified</dd></div></dl><button class="textlink" data-finding="${esc(i.findingId)}">${esc(i.findingId)} · Review evidence ↗</button></div>`).join('')||'<p class="empty">No actions in this bucket.</p>'}</section>`).join('')}</div>`;}}
function renderResults(){const matches=sorted().filter(f=>(state.severity==='all'||f.severity===state.severity)&&(f.title+' '+f.id+' '+(business()?window.PulseBusiness.title(f)+' '+f.businessRisk:'')).toLowerCase().includes(state.query.toLowerCase()));$('finding-results').innerHTML=matches.map(row).join('')||'<p class="empty" role="status">No findings match this selection.</p>';}
function finding(id){
  const f=report().findings.find(x=>x.id===id);if(!f)return;
  const technical=`${business()?`<h3>Technical finding</h3><p>${esc(f.title)}</p>`:''}<div class="finding-meta"><span class="pill">${esc(f.classification)}</span><span class="pill">${esc(f.confidence)} confidence</span></div><p class="section-note">${esc(f.id)} · score impact ${f.scoreImpact}</p><h3>Observed evidence</h3><div class="evidence">${esc(f.evidence.summary)}</div><h3>How to validate</h3>${f.validationSteps.length?`<ul>${f.validationSteps.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:'<p class="muted">The current report does not supply validation steps for this finding. Engineering review is required.</p>'}${f.falsePositiveNotes.length?`<h3>Context & exceptions</h3><ul>${f.falsePositiveNotes.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:''}<h3>Affected resources</h3><p>${esc(f.affectedResources.map(x=>x.displayName).join(', ')||'Not specified')}</p>`;
  $('finding-detail').innerHTML=`${severityPill(f.severity)}<h2 id="finding-title">${esc(business()?window.PulseBusiness.title(f):f.title)}</h2><h3>Why it matters</h3><p>${esc(business()?window.PulseBusiness.impact(f):f.businessRisk)}</p><h3>Recommended action</h3><p>${esc(f.recommendation)}</p>${business()?`<p class="section-note">${f.classification==='requires-validation'?'Engineering validation is needed before treating this as a confirmed risk.':'Review the observed configuration and its context with your technical contact.'}</p><details class="technical-evidence"><summary>Technical evidence & validation</summary>${technical}</details>`:technical}`;
  $('finding-dialog').showModal();
}
document.addEventListener('click',e=>{const v=e.target.closest('[data-view]'),f=e.target.closest('[data-finding]');if(v){state.view=business()&&v.dataset.view==='coverage'?'nis2':v.dataset.view;render();if(v.hasAttribute('data-evidence-limits')){const limits=$('material-scope');if(limits){limits.open=true;limits.querySelector('summary').focus();limits.scrollIntoView({block:'start'});}}else if(v.getAttribute('role')==='tab')$('tab-'+state.view).focus();}if(f)finding(f.dataset.finding);if(e.target.closest('[data-generate-pack]'))generatePack();});$('provider').addEventListener('change',e=>{state.provider=e.target.value;window.PulseExperience.updateContext(state.provider,state.scenario);render();});$('scenario').addEventListener('change',e=>{state.scenario=e.target.value;window.PulseExperience.updateContext(state.provider,state.scenario);render();});$('close-finding').onclick=()=>$('finding-dialog').close();$('export-json').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(report(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`identity-pulse-${state.provider}-${state.scenario}-sample.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const steps=['Read local assessment settings','Collect provider configuration · GET only','Normalize snapshot & collection status','Run provider-specific deterministic rules','Calculate scores & explain findings','Render local reports'];let scanStep=0,scanTimer=null;function scanDraw(){document.querySelector('[role=progressbar]').setAttribute('aria-valuenow',scanStep);$('scan-progress').style.width=(scanStep/6*100)+'%';$('scan-steps').innerHTML=steps.map((s,i)=>`<li class="${i===scanStep?'active':''}"><span>${s}</span><span>${i<scanStep?'✓':i===scanStep?'…':'—'}</span></li>`).join('');$('scan-status').textContent=scanStep===6?'Walkthrough complete. The workspace shows the selected fixture report.':`Step ${scanStep+1} of 6 · simulated processing`;$('scan-pause').textContent=scanStep===6?'Replay':scanTimer?'Pause':'Continue';}function pauseScan(){clearInterval(scanTimer);scanTimer=null;}function playScan(){scanTimer=setInterval(()=>{scanStep++;if(scanStep>=6)pauseScan();scanDraw();},850);scanDraw();}$('run-demo').onclick=()=>{pauseScan();scanStep=0;$('scan-dialog').showModal();playScan();};$('scan-pause').onclick=()=>{if(scanStep===6)scanStep=0;if(scanTimer)pauseScan();else playScan();scanDraw();};$('scan-close').onclick=()=>$('scan-dialog').close();$('scan-dialog').addEventListener('close',pauseScan);
function renderTabs(){
  const views=business()?[['nis2','NIS2 Material'],['findings','Findings'],['plan','Action Plans']]:[['overview','Overview'],['findings','Findings'],['coverage','Coverage'],['plan','Action Plans'],['nis2','NIS2 Material']];
  if(!views.some(([id])=>id===state.view))state.view=business()?'nis2':'overview';
  $('assessment-tabs').innerHTML=views.map(([id,label])=>`<button id="tab-${id}" type="button" role="tab" tabindex="${id===state.view?'0':'-1'}" aria-selected="${id===state.view}" aria-controls="assessment-view" data-view="${id}">${label}</button>`).join('');
  $('review-coverage').dataset.view=business()?'nis2':'coverage';
  $('review-coverage').textContent=business()?'Scope & evidence':'Review coverage';
}
function renderMaterial(){
  if(business()){$('assessment-view').innerHTML=window.PulseBusiness.material(report(),window.PULSE_CONTROLS[state.provider][state.scenario]);return;}
  const r=report(),uncollected=r.coverage.collectors.filter(c=>c.status!=='success');
  $('assessment-view').innerHTML=`<section class="material-hero"><div><span class="eyebrow">NIS2 Material</span><h2>Bring the evidence together.</h2><p>Prepare a clear record of what was checked, what needs attention and what still needs verification.</p><span class="pill light">Sample export · proposed capability</span></div><button class="button primary" id="generate-pack" data-generate-pack>Generate evidence pack</button></section><div class="material-grid">${[['01','What was checked',r.coverage.collectors.length+' collectors listed, with their status, scope and collection date.'],['02','Gaps & blind spots',r.findings.length+' findings · '+uncollected.length+' unsuccessful collectors.'],['03','How gaps were addressed','Recommended actions are available. Completed work, owners and validation evidence are not recorded.'],['04','Controls & policies','Observed MFA and protection settings, with unavailable evidence clearly marked.']].map(([n,title,text])=>`<article class="panel"><span class="material-number">${n}</span><h3>${title}</h3><p>${text}</p></article>`).join('')}</div><div class="notice neutral"><strong>For auditor review.</strong> This sample pack supports evidence preparation. It does not certify NIS2 compliance. Organizational policies and bot protection evidence have not been supplied.</div><details class="material-scope"><summary>Review collection gaps and assessment limits</summary><h3>Unsuccessful collectors</h3>${uncollected.length?`<ul>${uncollected.map(c=>`<li>${esc(c.collector)} · ${esc(c.status)}</li>`).join('')}</ul>`:'<p>No collector gaps reported. Collection success does not guarantee exhaustive coverage.</p>'}<h3>Limitations</h3><ul>${r.limitations.map(l=>`<li>${esc(l)}</li>`).join('')}</ul></details>`;
}
function generatePack(){
    currentPack=window.PulseEvidence.build(report(),window.PULSE_CONTROLS[state.provider][state.scenario],$('scenario').selectedOptions[0].textContent);
    $('pack-preview').innerHTML=window.PulseEvidence.content(currentPack,true);
    if(currentPackURL)URL.revokeObjectURL(currentPackURL);
    currentPackURL=URL.createObjectURL(new Blob([window.PulseEvidence.html(currentPack)],{type:'text/html;charset=utf-8'}));
    $('download-pack').href=currentPackURL;
    $('download-pack').download=`identity-pulse-${currentPack.report.provider.id}-sample-evidence-pack.html`;
    $('pack-download-status').textContent='Self-contained HTML · browser mockup';
    $('pack-dialog').showModal();
}
let currentPack=null,currentPackURL=null;
$('close-pack').onclick=()=>$('pack-dialog').close();
$('download-pack').onclick=()=>{
  $('pack-download-status').textContent='Sample HTML download requested. Open the file to review or print.';
};

$('assessment-tabs').addEventListener('keydown',event=>{
  const tabs=[...$('assessment-tabs').querySelectorAll('[role=tab]')],index=tabs.indexOf(event.target);
  if(index<0||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(event.key))return;
  event.preventDefault();
  const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(['ArrowRight','ArrowDown'].includes(event.key)?1:-1)+tabs.length)%tabs.length;
  state.view=tabs[next].dataset.view;render();$('tab-'+state.view).focus();
});
$('provider').value=state.provider;
$('scenario').value=state.scenario;
const requestedView=new URLSearchParams(location.search).get('view');
if(['overview','findings','coverage','plan','nis2'].includes(requestedView))state.view=requestedView;
if(business()){
  $('business-navigation').append($('assessment-tabs'));
  $('assessment-tabs').setAttribute('aria-label','Business workspace');
  $('workspace-title').textContent='Risk, actions & evidence';
  $('workspace-eyebrow').textContent='Business overview';
  $('workspace-heading').textContent='Know what needs your attention.';
  $('workspace-intro').textContent='Prioritize the risks, agree ownership and prepare the evidence for review.';
  document.title='Identity Pulse — Business workspace';
}else document.title='Identity Pulse — Tech SPOC workspace';
function tabOrientation(){$('assessment-tabs').setAttribute('aria-orientation',business()&&innerWidth>850?'vertical':'horizontal');}
window.addEventListener('resize',tabOrientation);tabOrientation();
render();
